function validate([words, s]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  if (words.some(w => typeof w !== 'string' || w.length < 1 || w.length > 10)) return 'Each word has 1 to 10 letters.';
  if (words.some(w => !/^[a-z]+$/.test(w))) return 'Words use only lowercase English letters.';
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's has 1 to 100 letters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  return null;
}

