function isAcronym(words, s) {
  if (words.length !== s.length) {
    return false;
  }
  for (let i = 0; i < words.length; i++) {
    if (words[i][0] !== s[i]) {
      return false;
    }
  }
  return true;
}

brute:
function isAcronym(words, s) {
  let built = '';
  for (const word of words) built += word.charAt(0);
  return built === s;
}

