function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const word = maxLen => Array.from({ length: 1 + Math.floor(rand() * maxLen) }, pick).join('');
  const count = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const words = Array.from({ length: count }, () => word(size === 'large' ? 10 : 3));
  let s = words.map(w => w[0]).join('');
  const mode = rand();
  if (mode < 0.5) return [words, s];
  if (mode < 0.7) {
    // Change one letter of the acronym.
    const at = Math.floor(rand() * s.length);
    const other = letters[(letters.indexOf(s[at]) + 1) % letters.length];
    s = s.slice(0, at) + other + s.slice(at + 1);
  } else if (mode < 0.8 && s.length > 1) {
    s = s.slice(0, -1);
  } else if (mode < 0.9 && s.length < 100) {
    s += pick();
  } else {
    s = word(size === 'large' ? 100 : 6);
  }
  return [words, s];
}
